def semver_sort(versions):
    def parse(v):
        core = v
        build = None
        if '+' in core:
            core, build = core.split('+', 1)
        pre = None
        if '-' in core:
            core, pre = core.split('-', 1)
        major, minor, patch = (int(x) for x in core.split('.'))
        pre_ids = pre.split('.') if pre is not None else []
        return major, minor, patch, pre_ids

    def key(v):
        major, minor, patch, pre_ids = parse(v)
        has_pre = 1 if pre_ids else 0
        # prerelease sorts before no-prerelease -> flag: 0 if has_pre else 1
        flag = 0 if has_pre else 1
        pre_key = []
        for ident in pre_ids:
            if ident.isdigit():
                pre_key.append((0, int(ident)))
            else:
                pre_key.append((1, ident))
        return (major, minor, patch, flag, pre_key)

    indexed = list(enumerate(versions))
    indexed.sort(key=lambda pair: (key(pair[1]), pair[0]))
    return [v for i, v in indexed]

